function countBinarySubstrings(s) {
  let previous = 0;
  let current = 1;
  let count = 0;

  for (let i = 1; i < s.length; i++) {
    if (s[i] === s[i - 1]) {
      current++;
    } else {
      count += Math.min(previous, current);
      previous = current;
      current = 1;
    }
  }
  count += Math.min(previous, current);
  return count;
}

