function countBinarySubstrings(s) {
  // Check every substring directly: equal counts and at most one switch between digits.
  let total = 0;
  for (let start = 0; start < s.length; start++) {
    let zeros = 0;
    let ones = 0;
    let switches = 0;
    for (let end = start; end < s.length; end++) {
      if (end > start && s[end] !== s[end - 1]) switches++;
      if (switches > 1) break;
      if (s[end] === '0') zeros++;
      else ones++;
      if (zeros === ones) total++;
    }
  }
  return total;
}

