function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const length = size === 'large' ? 9000 + pick(1001) : 1 + pick(14);
  // Build the string from runs; the longest run varies so short and long blocks both appear.
  const longest = size === 'large' ? [1, 3, 20, 400][pick(4)] : 1 + pick(5);
  let s = '';
  let digit = rand() < 0.5 ? '0' : '1';
  while (s.length < length) {
    s += digit.repeat(Math.min(length - s.length, 1 + pick(longest)));
    digit = digit === '0' ? '1' : '0';
  }
  return [s];
}
